function d_feature_importance(P,R){var feats=P.features||['f1','f2','f3','f4'];var base=0.85;var imp=feats.map(function(f){var drop=R()*0.3;return{feature:f,importance:+(drop).toFixed(3),acc_after_shuffle:+(base-drop).toFixed(3)};});imp.sort(function(a,b){return b.importance-a.importance;});return{baseline_acc:base,ranking:imp};}

